{
  "justification": "Issue salience is dominated by the economy, with a centrist tax–spend mean, pointing to a blend of proportionality (merit, prudence) and equality (fair provision). Immigration is the second concern and EU views are net negative, elevating loyalty (in-group protection) with auxiliary authority cues from crime/terrorism, while low explicit moral/religious salience keeps sanctity relatively weak.",
  "foundations": [
    {"foundation": "proportionality", "basis": "Economy general 46.8% and tax–spend mean 5.05/10 (Slots 3,5) emphasize reward-for-contribution and fiscal prudence.", "weight": 0.25},
    {"foundation": "loyalty", "basis": "Immigration salience 18.6% and net EU disapproval (50.1% vs 31.8% approve) indicate national/group allegiance (Slots 3,7).", "weight": 0.22},
    {"foundation": "authority", "basis": "Crime 6.3%, terrorism 1.5%, national security 0.2% and strikes 0.2% point to law-and-order priorities (Slot 3).", "weight": 0.18},
    {"foundation": "equality", "basis": "Economic concern alongside unemployment 3.7%, NHS 1.1%, education 0.8%, pensions 0.6% and class difference 0.6% (Slots 3,5).", "weight": 0.18},
    {"foundation": "care", "basis": "Unemployment 3.7%, NHS 1.1%, environment 1.5%, youth 0.7% and aging population 0.4% reflect harm/benefit sensitivities (Slot 3).", "weight": 0.11},
    {"foundation": "sanctity", "basis": "Low but present concerns—family values-lack 0.4%, morals 0.3%, drugs 0.5%, environment 1.5%, failure of religious 0.1% (Slot 3).", "weight": 0.06}
  ]
}
